1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Normalization for the owner {@code address}, applied whenever an owner is created.
8	 *
9	 * <p>Rules: trim the ends and collapse runs of whitespace to a single space, upper-case, and
10	 * expand common street-type abbreviations ({@code ST -> STREET}, {@code RD -> ROAD},
11	 * {@code AVE -> AVENUE}). So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and
12	 * {@code "7 elm ave"} becomes {@code "7 ELM AVENUE"}.
13	 *
14	 * <p>The normalized value is what {@link ValidateOwnerFields} stores on the request (so it is
15	 * persisted and returned) and is the form used for every address comparison — the required-field
16	 * check (a value blank after normalization is rejected), the duplicate identityKey
17	 * ({@link EnsureUniqueOwnerIdentity}) and the shared household id ({@link AssignOwnerHousehold}).
18	 * The transformation is idempotent, so re-normalizing an already-normalized value is a no-op.
19	 *
20	 * <p>The same normalization applies to the structured address fields ({@code addressLine1} /
21	 * {@code addressLine2}). When {@code addressLine1} is supplied the structured form is preferred:
22	 * {@link #compose} joins the normalized {@code addressLine1} with the normalized
23	 * {@code addressLine2} (single space, only when present) to form the composed {@code address}
24	 * that is persisted and returned; otherwise the flat {@code address} is used.
25	 */
26	final class OwnerAddress {
27	
28	    /** Common street-type abbreviations expanded to their full (upper-cased) form. */
29	    private static final Map<String, String> ABBREVIATIONS = Map.of(
30	            "ST", "STREET",
31	            "RD", "ROAD",
32	            "AVE", "AVENUE");
33	
34	    private OwnerAddress() {
35	    }
36	
37	    /**
38	     * Normalize a raw address; {@code null} stays {@code null} and a value that is only whitespace
39	     * normalizes to the empty string.
40	     */
41	    static String normalize(String raw) {
42	        if (raw == null) {
43	            return null;
44	        }
45	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
46	        if (collapsed.isEmpty()) {
47	            return "";
48	        }
49	        String[] tokens = collapsed.split(" ");
50	        StringBuilder sb = new StringBuilder(collapsed.length());
51	        for (int i = 0; i < tokens.length; i++) {
52	            if (i > 0) {
53	                sb.append(' ');
54	            }
55	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
56	        }
57	        return sb.toString();
58	    }
59	
60	    /**
61	     * Compose a display address from already-normalized structured lines: {@code line1}, with a
62	     * single space and {@code line2} appended when {@code line2} is present (non-null and not
63	     * blank).
64	     */
65	    static String compose(String line1, String line2) {
66	        if (line2 != null && !line2.isBlank()) {
67	            return line1 + " " + line2;
68	        }
69	        return line1;
70	    }
71	}
