35	        if (value == null) {
36	            return "null";
37	        }
38	        StringBuilder sb = new StringBuilder(value.length() + 2);
39	        sb.append('"');
40	        for (int i = 0; i < value.length(); i++) {
41	            char c = value.charAt(i);
42	            switch (c) {
